"""Untangle Trails preview, support and policy from current native build evidence."""
from pathlib import Path
from html import escape
from bs4 import BeautifulSoup
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
def build(page):
 base='/assets/apps/untangle-trails/'
 captions=['Nautical home menu and free play','Campaign puzzle on the rectangular ivory board','Expert scramble with a dense cord network','Guided tutorial with a cyan target ring','Chapter selection and earned stars','Saved campaign progress']
 shots=''
 for i,caption in enumerate(captions,1):
  im=Image.open(ROOT/f'assets/apps/untangle-trails/screenshot-{i}.png').convert('RGB');im.thumbnail((720,1400));im.save(ROOT/f'assets/apps/untangle-trails/screenshot-{i}.webp','WEBP',quality=85)
  shots+=f'<figure><a href="{base}screenshot-{i}.webp"><img src="{base}screenshot-{i}.webp" width="{im.width}" height="{im.height}" alt="{caption}" loading="lazy"></a><figcaption>{caption}</figcaption></figure>'
 body=f'<section class="catalog-hero"><p class="eyebrow">Android puzzle game · Coming soon</p><h1>Untangle Trails</h1><p class="lead">Find a clearer path, one peg at a time.</p><p>Move numbered pegs across an ivory puzzle board until every cord is clear. Brass trim, ocean-teal details and a nautical backdrop give this quiet logic game a physical feel.</p><img src="{base}feature.png" width="1024" height="500" style="width:100%;height:auto;border-radius:16px" alt="Untangle Trails and its rectangular puzzle board"><p>In development for Android. Not yet available on Google Play.</p></section><section><h2>Untangle your way through 100 puzzles</h2><p>Work through ten campaign chapters, earn up to three stars and revisit puzzles to improve your move count. Any valid arrangement with zero crossings wins; there is no single required final layout. Fixed gold pegs add another planning challenge.</p><h2>Play at your pace</h2><p>Start untimed, or enable the optional timer. Free Play offers Easy, Standard and Expert scrambles separately from campaign progress. Use hints, undo and restart when you need another approach.</p><p>Numbered pegs, optional cord patterns, board guides, vibration and reduced-motion settings help you make the board your own. Puzzle gameplay works offline and progress stays on your device, without a player account.</p><h2>Ads and purchases</h2><p>The Android build includes interstitial ads between rounds, scheduled after every two completed non-tutorial puzzles when an ad is available. Ads do not interrupt a move. An optional permanent Remove Ads purchase is planned through Google Play; checkout and regional prices will be available with the store release.</p></section><section><h2>See the current game</h2><p>Actual Android development-build screenshots captured on a phone. Features may change before release.</p><div class="screenshots">{shots}</div></section><p><a href="/untangle-trails/privacy/">App privacy policy</a> · <a href="/untangle-trails/support/">Help and feedback</a></p>'
 page('/untangle-trails/','Untangle Trails — Nautical Untangling Puzzles for Android','Untangle crossing cords in 100 nautical puzzles, with free play, hints and a spacious ivory board. Coming soon for Android.',body,'https://tripperdeelabs.com'+base+'feature.png',{'@context':'https://schema.org','@type':'SoftwareApplication','name':'Untangle Trails','operatingSystem':'Android','applicationCategory':'GameApplication','url':'https://tripperdeelabs.com/untangle-trails/','image':'https://tripperdeelabs.com'+base+'icon.png'})
 policy=(ROOT/'data/untangle-privacy.txt').read_text().split('\n\n')
 body='<section><h1>Untangle Trails privacy policy</h1>'+''.join('<p>'+escape(p)+'</p>' for p in policy)+'<h2>This website</h2><p>This game policy is separate from the <a href="/privacy/">website privacy policy</a>, which covers optional website analytics.</p><p><a href="/untangle-trails/">Game overview</a> · <a href="/untangle-trails/support/">Support</a></p></section>'
 page('/untangle-trails/privacy/','Untangle Trails privacy policy','Privacy information for Untangle Trails: local progress, Google AdMob, consent, Google Play purchases and support.',body)
 page('/untangle-trails/support/','Untangle Trails support','How to play Untangle Trails, preserve progress, restore purchases and contact TripperDeeLabs.','<section><h1>Untangle Trails support</h1><h2>Clear every crossing</h2><p>Drag numbered pegs until no cords cross. Gold-ringed fixed pegs stay in place. Any valid clear arrangement wins. The guided tutorial shows your first move.</p><h2>Hints and progress</h2><p>Hints reveal one valid solution and affect your star rating. Undo lets you reconsider a move. Avoid clearing app storage or uninstalling while troubleshooting, because local progress can be lost.</p><h2>Ads, purchases and privacy</h2><p>Use the settings gear for Remove Ads, purchase restoration and privacy choices when available. Purchases require Google Play connectivity and the account used to buy them. The game is not yet publicly available on Google Play.</p><h2>Contact</h2><p>Email <a href="mailto:TripperDeeLabs@gmail.com?subject=Untangle%20Trails%20feedback">feedback@tripperdeelabs.com</a> with your game version, phone model and what happened. Do not send passwords or payment details.</p><p><a href="/untangle-trails/">Game overview</a> · <a href="/untangle-trails/privacy/">Privacy policy</a></p></section>')
 home=ROOT/'index.html';soup=BeautifulSoup(home.read_text(),'html.parser');listing=soup.select_one('#in-development .app-directory')
 assert listing is not None
 example=listing.find('li');item=BeautifulSoup(f'<li><a class="directory-preview" href="/untangle-trails/"><img src="{base}screenshot-2.webp" width="540" height="1054" loading="lazy" alt="Untangle Trails rectangular puzzle board"></a><div class="directory-copy"><h3><a href="/untangle-trails/">Untangle Trails</a></h3><p class="availability">Coming soon</p><p>Untangle crossing cords across 100 nautical puzzles. Move numbered pegs, earn stars and explore free-play scrambles on a spacious ivory board.</p><p><a href="/untangle-trails/">Explore the game</a> · <a href="/untangle-trails/privacy/">Privacy</a></p></div></li>','html.parser').li
 if example and example.get('class'):item['class']=example['class']
 listing.insert(0,item);home.write_text(str(soup))
